function debounce(fn, delay) {
  let timerId = null;

  return function(...args) {
    // 1. Cancel previous pending timer
    clearTimeout(timerId);

    // 2. Restart delay countdown
    timerId = setTimeout(() => {
      fn.apply(this, args);
    }, delay);
  };
}

