function deepClone(value, map = new WeakMap()) {
  // 1. Return primitives and null directly
  if (value === null || typeof value !== 'object') {
    return value;
  }

  // 2. Prevent infinite loops from circular references
  if (map.has(value)) {
    return map.get(value);
  }

  // 3. Initialize array or object container
  const clone = Array.isArray(value) ? [] : {};
  map.set(value, clone);

  // 4. Recursively copy properties
  for (const key of Object.keys(value)) {
    clone[key] = deepClone(value[key], map);
  }

  return clone;
}

// Test Circular Reference:
const original = { a: 1, nested: { b: 2 } };
original.self = original; // Circular loop!

const copied = deepClone(original);
console.log(copied.nested.b); // 2
console.log(copied.self === copied); // true (circularity correctly preserved!)

// Benchmark Example: Array shift() vs Index Increment Pointer
const N = 100000;
const arr = new Array(N).fill(1);

// ❌ Inefficient: shift() takes O(N^2) total time for N elements
console.time('shift');
const arrCopy = [...arr];
while (arrCopy.length > 0) {
  arrCopy.shift(); // O(N) operation inside O(N) loop!
}
console.timeEnd('shift'); // ~2000ms!

// ✅ Efficient: Pointer increment takes O(N) total time
console.time('pointer');
let head = 0;
while (head < arr.length) {
  head++; // O(1) operation inside O(N) loop!
}
console.timeEnd('pointer'); // ~1ms!

var twoSum = function(nums, target) {
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      if (nums[i] + nums[j] === target) {
        return [i, j];
      }
    }
  }
  return [];
};

// =========================================

/**
 * @param {number[]} nums
 * @param {number} target
 * @return {number[]}
 */
var twoSum = function(nums, target) {
  const map = new Map(); // value -> index

  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];

    if (map.has(complement)) {
      return [map.get(complement), i];
    }

    map.set(nums[i], i);
  }

  return [];
};

var isAnagram = function(s, t) {
  if (s.length !== t.length) return false;
  return s.split('').sort().join('') === t.split('').sort().join('');
};

