var moveZeroes = function(nums) {
  const temp = [];
  for (const x of nums) if (x !== 0) temp.push(x);
  while (temp.length < nums.length) temp.push(0);
  for (let i = 0; i < nums.length; i++) nums[i] = temp[i];
};

